function bbs_card_qr_limit(string $token): array {
    global $config;$ip=(string)($_SERVER['REMOTE_ADDR']??'unknown');$ipHash=hash('sha256',(string)$config['jwt_secret'].':'.$ip);$fingerprint=bbs_card_fingerprint($token);$setting=db_row("SELECT SettingValue FROM BBS_Settings WHERE SettingKey='qr_resolve_limit_5m' LIMIT 1");$limit=max(5,min(200,(int)($setting['SettingValue']??30)));$row=db_row('SELECT COUNT(*) count FROM BBS_QR_Resolve_Attempts WHERE IPHash=? AND AttemptedAt>=DATE_SUB(NOW(),INTERVAL 5 MINUTE)',[$ipHash]);return['allowed'=>(int)($row['count']??0)<$limit,'ipHash'=>$ipHash,'fingerprint'=>$fingerprint];
}
function bbs_card_record_resolve(array $state,bool $success): void { db_execute('INSERT INTO BBS_QR_Resolve_Attempts(IPHash,TokenFingerprint,Successful) VALUES(?,?,?)',[$state['ipHash'],$state['fingerprint'],$success?1:0]); }
function bbs_card_active_token(string $token,?PDO $pdo=null): ?array { $pdo=$pdo?:db();$stmt=$pdo->prepare("SELECT c.*,t.Status TemplateStatus FROM BBS_Cards c JOIN BBS_Card_Templates t ON t.id=c.TemplateID WHERE c.TokenHash=? AND c.Status='Active' AND t.Status='Active' LIMIT 1");$stmt->execute([bbs_card_hash($token)]);$row=$stmt->fetch();return$row?:null; }
