function bbs_card_can_target(array $user,array $card): bool { $uid=(string)($user['id']??'');if(strcasecmp((string)($user['role']??''),'Admin')===0||strcasecmp($uid,(string)$card['EmployeeID'])===0)return true;$date=(new DateTimeImmutable('now',new DateTimeZone('Asia/Bangkok')))->format('Y-m-d');return(bool)db_row("SELECT id FROM BBS_Hierarchy_Assignments WHERE SupervisorEmployeeID=? AND MemberEmployeeID=? AND IsActive=1 AND EffectiveFrom<=? AND (EffectiveTo IS NULL OR EffectiveTo>=?) LIMIT 1",[$uid,$card['EmployeeID'],$date,$date]); }
function bbs_card_designer_rendering_enabled(?PDO $pdo=null): bool { $pdo=$pdo?:db();$stmt=$pdo->prepare("SELECT SettingValue FROM BBS_Settings WHERE SettingKey='visual_card_designer_rendering_enabled' LIMIT 1");$stmt->execute();return(string)($stmt->fetch()['SettingValue']??'0')==='1'; }
function bbs_card_designer_safe_layout(array $version,array $sides,array $elements,array $assets): array { $assetByStored=[];foreach($assets as$asset)$assetByStored[(string)$asset['StoredName']]=(int)$asset['id'];return['layoutVersionId'=>(int)$version['id'],'versionNo'=>(int)$version['VersionNo'],'widthMM'=>(float)$version['WidthMM'],'heightMM'=>(float)$version['HeightMM'],'dpi'=>(int)$version['DPI'],'duplexFlip'=>(string)$version['DuplexFlip'],'backRotation'=>(int)$version['BackRotation'],'sides'=>array_map(fn($side)=>['side'=>(string)$side['Side'],'storageClass'=>(string)$side['StorageClass'],'backgroundAssetId'=>$side['StorageClass']==='DesignerAsset'?($assetByStored[(string)$side['BackgroundStoredName']]??null):null,'backgroundUrl'=>'/bbs/admin/card-designer/versions/'.(int)$version['id'].'/sides/'.strtolower((string)$side['Side']).'/background','backgroundFit'=>(string)$side['BackgroundFit'],'backgroundPositionXBP'=>(int)$side['BackgroundPositionXBP'],'backgroundPositionYBP'=>(int)$side['BackgroundPositionYBP'],'bleedMM'=>(float)$side['BleedMM'],'safeMarginMM'=>(float)$side['SafeMarginMM']],$sides),'elements'=>array_map(fn($element)=>['elementKey'=>(string)$element['ElementKey'],'side'=>(string)$element['Side'],'elementType'=>(string)$element['ElementType'],'dataSourceKey'=>$element['DataSourceKey']?:null,'staticText'=>$element['StaticText']?:null,'assetId'=>$element['AssetID']===null?null:(int)$element['AssetID'],'assetUrl'=>$element['AssetID']===null?null:'/bbs/admin/card-designer/assets/'.(int)$element['AssetID'].'/file','xBP'=>(int)$element['XBP'],'yBP'=>(int)$element['YBP'],'widthBP'=>(int)$element['WidthBP'],'heightBP'=>(int)$element['HeightBP'],'rotationDeg'=>(int)$element['RotationDeg'],'zIndex'=>(int)$element['ZIndex'],'visible'=>(bool)$element['Visible'],'style'=>json_decode((string)($element['StyleJSON']??'{}'),true)?:[]],$elements),'assets'=>array_map(fn($asset)=>['id'=>(int)$asset['id'],'assetKey'=>(string)$asset['AssetKey'],'originalName'=>(strin