function bbs_card_active_personal_designer_layout(PDO $pdo,int $templateId): ?array { try{$stmt=$pdo->prepare("SELECT * FROM BBS_Card_Layout_Versions WHERE PersonalTemplateID=? AND TemplateKind='Personal' AND Status='Active' LIMIT 1");$stmt->execute([$templateId]);$version=$stmt->fetch();if(!$version)return null;$stmt=$pdo->prepare("SELECT * FROM BBS_Card_Layout_Sides WHERE LayoutVersionID=? ORDER BY FIELD(Side,'Front','Back')");$stmt->execute([(int)$version['id']]);$sides=$stmt->fetchAll();$stmt=$pdo->prepare("SELECT * FROM BBS_Card_Layout_Elements WHERE LayoutVersionID=? ORDER BY FIELD(Side,'Front','Back'),ZIndex,id");$stmt->execute([(int)$version['id']]);$elements=$stmt->fetchAll();$stmt=$pdo->prepare("SELECT * FROM BBS_Card_Layout_Assets WHERE LayoutVersionID=? AND Status='Active' ORDER BY id");$stmt->execute([(int)$version['id']]);return bbs_card_designer_safe_layout($version,$sides,$elements,$stmt->fetchAll());}catch(PDOException$e){if((int)($e->errorInfo[1]??0)===1146)return null;throw$e;} }
function bbs_card_designer_personal_render(PDO $pdo,array $employee,array $template,array $card,string $token,string $actor): ?array { if(!bbs_card_designer_rendering_enabled($pdo))return null;$layout=bbs_card_active_personal_designer_layout($pdo,(int)$template['id']);if(!$layout)return null;$values=['employee.full_name'=>(string)($employee['EmployeeName']??''),'employee.id'=>(string)($employee['EmployeeID']??''),'employee.department'=>(string)($employee['Department']??''),'employee.safety_unit'=>(string)($employee['Unit']??''),'employee.position'=>(string)($employee['Position']??''),'employee.bbs_level'=>(string)($employee['BBSLevel']??''),'employee.photo'=>'','card.personal_qr'=>(string)($card['qrUrl']??''),'card.issue_date'=>(new DateTimeImmutable('now',new DateTimeZone('Asia/Bangkok')))->format('Y-m-d'),'template.name'=>(string)($template['TemplateName']??''),'organization.name'=>'Thai Summit Harness Co., Ltd.','organization.logo'=>''];$snapshot=['layout'=>$layout,'values'=>array_replace($values,['card.personal_qr'=>['kind'=>'PersonalQr','fingerprint'=>bbs_card_fingerprint($token)]])];return['layout'=>$layout,'values'=>$values,'printSnapshot'=>['layoutVersionId'=>$layout['layoutVersionId'],'renderContractHash'=>hash('sha256',(string)json_encode($snapshot,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)),'snapshot'=>$snapshot,'receipt'=>bbs_print_receipt_create('Personal',(int)$card['cardId'],$actor,$snapshot)]]; }
function bbs_card_issue(PDO $pdo,array $user,array $employee,array $template,string $reason): array { $token=bbs_card_token();$stmt=$pdo->prepare("INSERT INTO BBS_Cards(EmployeeID,TemplateID,TokenHash,TokenFingerprint,Status,IssueReason,IssuedBy) VALUES(?,?,?,?,'Active',?,?)");$stmt->execute([$employee['EmployeeID'],$template['id'],bbs_card_hash($token),bbs_card_fingerprint($token),$reason!==''?$reason:null,(string)$user['id']]);$payload=array_merge(['cardId'=>(int)$pdo->lastInsertId(),'rawToken'=>$token],bbs_card_payload($employee,$template,$token));$render=bbs_card_designer_personal_render($pdo,$employee,$template,$payload,$token,(string)$user['id']);return$render?array_merge($payload,['designerRender'=>$render]):$payload; }
function bbs_card_upload(): array {
    $file=$_FILES['template']??null;if(!is_array($file)||(int)($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)json_response(['success'=>false,'message'=>'A JPG, PNG, or WebP card template is required.'],400);if((int)($file['size']??0)>10*1024*1024)json_response(['success'=>false,'message'=>'Template must not exceed 10 MB.'],400);$mime=bbs_card_file_mime((string)$file['tmp_name']);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true))json_response(['success'=>false,'message'=>'Template file content is not a supported image.'],400);$ext=['image/jpeg'=>'.jpg','image/png'=>'.png','image/webp'=>'.webp'][$mime];$stored=time().'-'.bin2hex(random_bytes(18)).$ext;$target=bbs_card_template_dir().'/'.$stored;if(!move_uploaded_file((string)$file['tmp_name'],$target))json_response(['success'=>false,'message'=>'Unable to store card template.'],500);return['stored'=>$stored,'name'=>bbs_card_clean($file['name']??'template',255),'mime'=>$mime,'size'=>(int)$file['size'],'target'=>$target];
}

