    if($method==='GET'&&$path==='/bbs/admin/card-employees'){$paging=bbs_list_query($_GET,24);$q=bbs_list_search($_GET['q']??'');$departmentId=bbs_phase1_positive_int($_GET['departmentId']??null);$where=["FIELD(m.BBSLevel,'Operator','Group Leader','Department Head','Section Head','Manager')>=2"];$params=[];if($departmentId){$where[]='md.id=?';$params[]=$departmentId;}if($q!==''){$where[]='(e.EmployeeID LIKE ? OR e.EmployeeName LIKE ? OR e.Department LIKE ? OR e.Unit LIKE ? OR e.Position LIKE ?)';for($i=0;$i<5;$i++)$params[]='%'.$q.'%';}$from="FROM employees e JOIN master_positions p ON LOWER(TRIM(p.Name))=LOWER(TRIM(e.Position)) JOIN BBS_Position_Level_Mappings m ON m.PositionID=p.id AND m.IsActive=1 LEFT JOIN master_departments md ON LOWER(TRIM(md.Name))=LOWER(TRIM(e.Department)) LEFT JOIN BBS_Cards c ON c.id=(SELECT x.id FROM BBS_Cards x WHERE x.EmployeeID=e.EmployeeID AND x.Status='Active' ORDER BY x.id DESC LIMIT 1) WHERE ".implode(' AND ',$where);$select="SELECT e.EmployeeID,e.EmployeeName,e.Department,e.Unit,e.Position,m.BBSLevel,md.id DepartmentID,c.id ActiveCardID,c.TokenFingerprint,c.IssuedAt $from";if(!$paging['paged'])json_response(['success'=>true,'data'=>db_rows($select.' ORDER BY e.Department,e.Unit,e.EmployeeName',$params)]);$count=db_row("SELECT COUNT(*) total $from",$params);$meta=bbs_list_pagination((int)($count['total']??0),$paging['page'],$paging['pageSize']);json_response(['success'=>true,'data'=>['rows'=>db_rows($select.' ORDER BY e.Department,e.Unit,e.EmployeeName LIMIT '.(int)$meta['pageSize'].' OFFSET '.(($meta['page']-1)*$meta['pageSize']),$params),'pagination'=>$meta]]);}
