 BBS card(s).');json_response(['success'=>true,'data'=>$cards],201);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();if($e instanceof PDOException&&(int)($e->errorInfo[1]??0)===1062)json_response(['success'=>false,'code'=>'ACTIVE_CARD_EXISTS','message'=>'This employee already has an Active card. Use Replace.'],409);throw$e;}}
